//! Source service callers, not another service catalogue.
//!
//! The data is generated by the extraction pipeline from the area scripts and
//! the service contract.  It carries *callers*, service ids, requirements,
//! limits and explicit blockers.  No original address, LBA or offset reaches
//! gameplay code.
const std = @import("std");

pub const schema_id = "suikoden-service-callers/1";
pub const max_json_bytes = 1024 * 1024;

pub const ServiceFamily = enum { shop, warehouse, appraisal, blacksmith, rune };

pub const ServiceId = enum {
    shop_buy,
    shop_sell,
    warehouse_deposit,
    warehouse_withdraw,
    appraisal_appraise,
    blacksmith_sharpen,
    rune_attach,
    rune_detach,
};

pub const StockItem = struct {
    native_id: u16,
    name: []const u8,
    label: []const u8,
};

pub const Npc = struct {
    sprite_id: u16,
    interactive: bool,
    x: i32,
    y: i32,
};

pub const Access = struct {
    area: []const u8,
    requires_npc: bool,
    requires_service: bool,
    requires_story_gate: bool,
    story_gate: ?bool = null,
};

pub const Return = struct {
    kind: []const u8,
    caller_id: []const u8,
    continuation: []const u8,
};

pub const Authorization = struct {
    requirements: []const []const u8,
    conditional: []const []const u8 = &.{},
};

pub const Caller = struct {
    id: []const u8,
    area: []const u8,
    area_file: []const u8,
    room: u8,
    entity: u8,
    stream: u8,
    service: ServiceFamily,
    services: []const ServiceId,
    context: []const u8,
    selector: u8,
    screen: u8,
    via: []const u8,
    stock_source: []const u8,
    stock: []const StockItem = &.{},
    greeting: ?[]const u8 = null,
    level_limit: ?u8 = null,
    npc: Npc,
    access: Access,
    return_target: Return,
    authorization: Authorization,
    canonical: bool = true,
};

pub const OverlayEntry = struct {
    id: []const u8,
    service: ServiceFamily,
    family: []const u8,
    source: []const u8,
    entry: []const u8,
    caller_kind: []const u8,
    canonical: bool,
    lock_reason: []const u8,
};

pub const Service = struct {
    id: ServiceId,
    family: ServiceFamily,
    operation: []const u8,
    context: []const u8,
    requirements: []const []const u8,
    conditional: []const []const u8 = &.{},
    stock_source: []const u8,
};

pub const Limits = struct {
    appraisal_fee: u32,
    character_item_capacity: u8,
    warehouse_item_count_max: u8,
    weapon_level_max: u8,
    weapon_power_selector_max: u8,
    list_page_rows: u8,
};

pub const EntryContractPin = struct {
    schema: []const u8,
    candidate_commit: []const u8,
    reviewed_commit: []const u8,
    candidate_contract_sha256: []const u8,
    reviewed_contract_sha256: []const u8,
    planner_sha256: []const u8,
    state: []const u8,
    note: []const u8,
};

pub const Blocker = struct {
    id: []const u8,
    kind: []const u8,
    detail: []const u8,
    sites: []const []const u8 = &.{},
};

pub const Packet = struct {
    schema: []const u8,
    version: u8,
    pack: []const u8,
    entry_contracts: EntryContractPin,
    limits: Limits,
    services: []const Service,
    callers: []const Caller,
    overlay_entries: []const OverlayEntry = &.{},
    blockers: []const Blocker = &.{},

    pub fn validate(self: Packet) !void {
        if (!std.mem.eql(u8, self.schema, schema_id)) return error.UnsupportedServiceCallerSchema;
        if (self.version != 1) return error.UnsupportedServiceCallerVersion;
        if (self.callers.len == 0 or self.callers.len > 512) return error.InvalidServiceCallers;
        if (self.services.len != 8) return error.InvalidServiceCallers;
        if (!std.mem.eql(u8, self.entry_contracts.schema, "suikoden-service-entry-contracts/1")) return error.InvalidServiceCallers;
        if (!std.mem.eql(u8, self.entry_contracts.state, "candidate_only")) return error.InvalidServiceCallers;
        if (self.limits.appraisal_fee != 500) return error.InvalidServiceCallers;
        if (self.limits.character_item_capacity != 9) return error.InvalidServiceCallers;
        if (self.limits.warehouse_item_count_max != 254) return error.InvalidServiceCallers;
        if (self.limits.weapon_level_max != 16) return error.InvalidServiceCallers;
        if (self.limits.weapon_power_selector_max != 10) return error.InvalidServiceCallers;
        if (self.limits.list_page_rows != 5) return error.InvalidServiceCallers;

        var seen_services: [8]bool = @splat(false);
        for (self.services) |service| {
            const slot: usize = @backingInt(service.id);
            if (seen_services[slot]) return error.InvalidServiceCallers;
            seen_services[slot] = true;
            if (service.requirements.len == 0) return error.InvalidServiceCallers;
            if (!std.mem.eql(u8, service.context, contextOf(service.family))) return error.InvalidServiceCallers;
        }

        for (self.callers, 0..) |caller, index| {
            if (caller.id.len == 0 or caller.id.len > 96) return error.InvalidServiceCallers;
            if (!std.mem.eql(u8, caller.access.area, caller.area)) return error.InvalidServiceCallers;
            if (!std.mem.eql(u8, caller.return_target.caller_id, caller.id)) return error.InvalidServiceCallers;
            if (!std.mem.eql(u8, caller.return_target.kind, "caller_conversation")) return error.InvalidServiceCallers;
            if (caller.services.len == 0) return error.InvalidServiceCallers;
            for (caller.services) |id| {
                if (!hasService(self.services, id) or serviceFamily(self.services, id) != caller.service) {
                    return error.InvalidServiceCallers;
                }
            }
            if (caller.level_limit) |limit| if (limit < 1 or limit > self.limits.weapon_level_max) return error.InvalidServiceCallers;
            for (caller.stock) |stock| if (stock.native_id < 1 or stock.native_id > 179) return error.InvalidServiceCallers;
            if (caller.service == .shop and std.mem.eql(u8, caller.stock_source, "static_entry_list") and caller.stock.len == 0) {
                return error.InvalidServiceCallers;
            }
            for (self.callers[0..index]) |previous| if (std.mem.eql(u8, previous.id, caller.id)) return error.InvalidServiceCallers;
        }
        for (self.overlay_entries) |entry| {
            if (entry.canonical) return error.InvalidServiceCallers;
            if (entry.service != .warehouse) return error.InvalidServiceCallers;
            if (!std.mem.eql(u8, entry.lock_reason, "warehouse_caller_unresolved")) return error.InvalidServiceCallers;
        }
    }

    pub fn findCaller(self: Packet, id: []const u8) ?*const Caller {
        for (self.callers) |*entry| if (std.mem.eql(u8, entry.id, id)) return entry;
        return null;
    }

    pub fn findOverlay(self: Packet, id: []const u8) ?*const OverlayEntry {
        for (self.overlay_entries) |*entry| if (std.mem.eql(u8, entry.id, id)) return entry;
        return null;
    }
};

fn contextOf(family: ServiceFamily) []const u8 {
    return switch (family) {
        .shop => "shop_screen",
        .warehouse => "warehouse_screen",
        .appraisal => "appraisal_screen",
        .blacksmith => "blacksmith_screen",
        .rune => "rune_screen",
    };
}

fn hasService(services: []const Service, id: ServiceId) bool {
    for (services) |service| if (service.id == id) return true;
    return false;
}

fn serviceFamily(services: []const Service, id: ServiceId) ServiceFamily {
    for (services) |service| if (service.id == id) return service.family;
    unreachable;
}

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Packet) {
    if (bytes.len == 0 or bytes.len > max_json_bytes) return error.ServiceCallerPacketTooLarge;
    const parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{ .allocate = .alloc_always, .ignore_unknown_fields = true });
    errdefer parsed.deinit();
    try parsed.value.validate();
    return parsed;
}
